#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (ll)4e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<vector<pair<int,int>>> g(n+1);
    for (int i = 0; i < m; ++i) {
        int a,b,w; cin >> a >> b >> w;
        g[a].push_back({b,w});
        g[b].push_back({a,w});
    }

    vector<ll> dist(n+1, INF);
    vector<int> par(n+1, -1);
    dist[1] = 0;
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    pq.push({0,1});

    while (!pq.empty()) {
        auto [d,u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        if (u == n) break; // optional early exit
        for (auto &e : g[u]) {
            int v = e.first; int w = e.second;
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                par[v] = u;
                pq.push({dist[v], v});
            }
        }
    }

    if (dist[n] == INF) {
        cout << -1 << '\n';
        return 0;
    }

    vector<int> path;
    for (int v = n; v != -1; v = par[v]) path.push_back(v);
    reverse(path.begin(), path.end());
    for (size_t i = 0; i < path.size(); ++i) {
        if (i) cout << ' ';
        cout << path[i];
    }
    cout << '\n';

    return 0;
}

